    return months.map((month, index) => {
      const monthData = yearlyData.filter(record => 
        new Date(record.date).getMonth() === index
      );
      const totalEmission = monthData.reduce((sum, r) => sum + r.emissionAmount, 0);

      return {
        month: format(month, 'M月'),
