      .filter(r => r.category === 'scope2')
      .reduce((sum, r) => sum + r.emissionAmount, 0);
    const scope3 = yearlyData
      .filter(r => r.category === 'scope3')
      .reduce((sum, r) => sum + r.emissionAmount, 0);

    return [
