      { name: '范围二 (能源间接排放)', value: parseFloat((scope2 / 1000).toFixed(2)) },
      { name: '范围三 (其他间接排放)', value: parseFloat((scope3 / 1000).toFixed(2)) },
    ];
  }, [yearlyData]);

  const departmentData = useMemo(() => {
